'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const surnames=['김','이','박','최','정','강','조','윤','장','임'];const names=['민준','서연','지훈','수빈','현우','지우','도윤','하은','준서','서현','시우','민서','예준','지유','유준','수아','건우','예은','우진','채원'];
let guests=surnames.flatMap((s,i)=>names.map((n,j)=>({id:i*20+j+1,name:s+n,group:i<5?'신랑측':'신부측'}))), tables=Array.from({length:20},()=>({capacity:10,seats:Array(10).fill(null)})),selected=0,activeSeat=0,pending=null;
function notify(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').style.display='none',4200)}
function assignedIds(){return new Set(tables.flatMap(t=>t.seats).filter(x=>x!==null))}
function render(){const used=assignedIds();$('#total').innerHTML=guests.length+'<small>명</small>';$('#assigned').innerHTML=used.size+'<small>명</small>';$('#remaining').innerHTML=(guests.length-used.size)+'<small>명</small>';$('#capacity').innerHTML=tables.reduce((a,t)=>a+t.capacity,0)+'<small>석</small>';

$('#tables').innerHTML=tables.map((t,i)=>{let count=t.seats.filter(x=>x!==null).length;let {x,y}=HALL_LAYOUT.tables[i];return `<button class="table ${i===selected?'active':''} ${count===t.capacity?'full':''}" data-table="${i}" style="left:${x}%;top:${y}px" aria-label="${i+1}번 테이블, ${count}명 배정, ${t.capacity}석" aria-pressed="${selected===i}"><b>${i+1}</b><small>${count} / ${t.capacity}</small></button>`}).join('');
const t=tables[selected];$('#table-title').textContent=String(selected+1).padStart(2,'0')+'번 테이블';$('#table-count').textContent=t.seats.filter(x=>x!==null).length+' / '+t.capacity+'명';$('#seat-guide').textContent=(selected===10?'11시':'1시')+' 방향부터 시계 방향 순서'+([0,10].includes(selected)?' · 혼주 포함':'');$('#capacities').innerHTML=[8,9,10].map(n=>`<button data-capacity="${n}" class="${t.capacity===n?'active':''}" aria-pressed="${t.capacity===n}">${n}석</button>`).join('');
$('#seats').innerHTML=t.seats.slice(0,t.capacity).map((id,i)=>{const g=guests.find(g=>g.id===id);return `<div class="seat"><span class="seat-number">${String(i+1).padStart(2,'0')}</span><button class="seat-choice ${g?'filled':''}" data-seat="${i}" aria-label="${i+1}번 좌석 ${g?esc(g.name):'하객 선택'}"><span>${g?esc(g.name):'＋ 하객 선택'}</span><small>${g?esc(g.group)+' · #'+g.id:'⌄'}</small></button>${g?`<button class="clear" data-clear="${i}" aria-label="${esc(g.name)} 배정 취소">×</button>`:''}</div>`}).join('');}
function setCapacity(n){const t=tables[selected];if(![8,9,10].includes(n))throw Error('좌석 수는 8~10석입니다.');if(t.seats.slice(n).some(x=>x!==null)){notify('줄어드는 좌석의 하객 배정을 먼저 취소해 주세요.');return}t.capacity=n;render()}
function assign(table,seat,id){if(!Number.isInteger(table)||table<0||table>=20||!Number.isInteger(seat)||seat<0||seat>=tables[table].capacity||!guests.some(g=>g.id===id))throw Error('유효하지 않은 테이블, 좌석 또는 하객입니다.');if(assignedIds().has(id))throw Error('이미 배정된 하객입니다.');tables[table].seats[seat]=id;render()}
function candidates(){const q=$('#search').value.trim().toLowerCase(),used=assignedIds();const gs=guests.filter(g=>!used.has(g.id)&&(g.name+' '+g.group+' '+g.id).toLowerCase().includes(q));$('#candidates').innerHTML=gs.length?gs.map(g=>`<button data-guest="${g.id}"><span>${esc(g.name)}</span><small>${esc(g.group)} · #${g.id}</small></button>`).join(''):'<p>선택할 수 있는 하객이 없습니다.</p>'}
$('#tables').onclick=e=>{const b=e.target.closest('[data-table]');if(!b)return;selected=Number(b.dataset.table);render();if(innerWidth<=680) $('.editor').scrollIntoView({behavior:'smooth'})};$('#capacities').onclick=e=>{const b=e.target.closest('[data-capacity]');if(b)setCapacity(Number(b.dataset.capacity))};$('#seats').onclick=e=>{const clear=e.target.closest('[data-clear]');if(clear){tables[selected].seats[Number(clear.dataset.clear)]=null;render();return}const b=e.target.closest('[data-seat]');if(!b)return;activeSeat=Number(b.dataset.seat);$('#picker-table').textContent=`TABLE ${String(selected+1).padStart(2,'0')} · ${activeSeat+1}번 좌석`;$('#search').value='';candidates();$('#picker').showModal();$('#search').focus()};$('#close-picker').onclick=()=>$('#picker').close();$('#search').oninput=candidates;$('#candidates').onclick=e=>{const b=e.target.closest('[data-guest]');if(!b)return;try{assign(selected,activeSeat,Number(b.dataset.guest));$('#picker').close()}catch(err){notify(err.message)}};
function download(template=false){const wb=XLSX.utils.book_new();let rows=template?[{이름:'홍길동',구분:'신랑 친구'},{이름:'김하나',구분:'신부 직장'}]:guests.map(g=>{let ti=tables.findIndex(t=>t.seats.includes(g.id));return {이름:g.name,구분:g.group,테이블:ti<0?'':ti+1,좌석:ti<0?'':tables[ti].seats.indexOf(g.id)+1}});XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),'하객명단');if(!template)XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(tables.map((t,i)=>({테이블:i+1,좌석수:t.capacity}))),'테이블설정');XLSX.writeFile(wb,template?'하객명단_양식.xlsx':'결혼식_좌석배치.xlsx')}
$('#template').onclick=()=>download(true);$('#export').onclick=()=>download();$('#backup').onclick=()=>download();$('#import').onclick=()=>$('#file').click();$('#cancel-import').onclick=()=>{$('#import-dialog').close();pending=null};
function parseWorkbook(wb){const sheet=wb.Sheets['하객명단']||wb.Sheets[wb.SheetNames[0]],rows=XLSX.utils.sheet_to_json(sheet,{defval:''});if(!rows.length)throw Error('명단이 비어 있습니다.');if(!Object.keys(rows[0]).some(k=>k.trim()==='이름'))throw Error('첫 행에 ‘이름’ 열이 필요합니다. 엑셀 양식을 사용해 주세요.');let normalized=rows.map(r=>Object.fromEntries(Object.entries(r).map(([k,v])=>[k.trim(),v]))).filter(r=>String(r.이름??'').trim());if(!normalized.length)throw Error('이름을 입력한 행이 없습니다.');if(normalized.length>5000)throw Error('하객 명단은 최대 5,000명까지 가능합니다.');const nt=Array.from({length:20},()=>({capacity:10,seats:Array(10).fill(null)}));if(wb.Sheets['테이블설정']){for(const r of XLSX.utils.sheet_to_json(wb.Sheets['테이블설정'])){const ti=Number(r.테이블),cap=Number(r.좌석수);if(!Number.isInteger(ti)||ti<1||ti>20||![8,9,10].includes(cap))throw Error('테이블설정의 테이블은 1~20, 좌석수는 8~10이어야 합니다.');nt[ti-1].capacity=cap}}
const ng=normalized.map((r,i)=>{const g={id:i+1,name:String(r.이름).trim(),group:String(r.구분??'').trim()};let hasT=String(r.테이블??'').trim()!=='',hasS=String(r.좌석??'').trim()!=='';if(hasT||hasS){const ti=Number(r.테이블),si=Number(r.좌석);if(!hasT||!hasS||!Number.isInteger(ti)||ti<1||ti>20||!Number.isInteger(si)||si<1||si>nt[ti-1].capacity)throw Error(`${i+2}행의 테이블 또는 좌석 번호가 올바르지 않습니다.`);if(nt[ti-1].seats[si-1]!==null)throw Error(`${ti}번 테이블 ${si}번 좌석이 중복되었습니다.`);nt[ti-1].seats[si-1]=g.id}return g});return {guests:ng,tables:nt}}
$('#file').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>10*1024*1024)throw Error('10MB 이하 파일을 사용해 주세요.');const wb=XLSX.read(await file.arrayBuffer(),{type:'array'});pending={...parseWorkbook(wb),filename:file.name};const count=pending.tables.flatMap(t=>t.seats).filter(x=>x!==null).length;$('#import-summary').textContent=`${file.name} · 하객 ${pending.guests.length}명, 기존 배치 ${count}명${pending.guests.length>200?' · 200명을 초과하는 하객은 미배정으로 남습니다.':''}`;$('#import-dialog').showModal()}catch(err){pending=null;notify(err.message||'엑셀 파일을 읽지 못했습니다.')}};$('#confirm-import').onclick=()=>{if(!pending)return;guests=pending.guests;tables=pending.tables;selected=0;$('#source-label').textContent=pending.filename+' · '+guests.length+'명';pending=null;$('#import-dialog').close();render();notify('하객 명단을 교체했습니다.')};
render();
if(document.modelContext?.registerTool){for(const tool of [{name:'read_seating_plan',description:'현재 하객 명단과 테이블별 좌석 배치를 조회합니다.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({guests,tables})},{name:'assign_wedding_guest',description:'미배정 하객을 지정한 테이블과 좌석에 배정합니다. 번호는 1부터 시작합니다.',inputSchema:{type:'object',properties:{table:{type:'integer',minimum:1,maximum:20},seat:{type:'integer',minimum:1,maximum:10},guestId:{type:'integer'}},required:['table','seat','guestId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{assign(input.table-1,input.seat-1,input.guestId);return {assigned:true}}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch{}}}
